DELETE FROM `dev_config`
WHERE CONFIG_KEY IN (
    'RUNXIN_EMAIL_LOCAL_FROM',
    'RUNXIN_EMAIL_LOCAL_PASSWORD',
    'RUNXIN_EMAIL_TENCENT_SECRET_ID',
    'RUNXIN_EMAIL_TENCENT_SECRET_KEY',
    'RUNXIN_EMAIL_TENCENT_REGION_ID',
    'RUNXIN_EMAIL_ALIYUN_ACCESS_KEY_ID',
    'RUNXIN_EMAIL_ALIYUN_ACCESS_KEY_SECRET',
    'RUNXIN_EMAIL_ALIYUN_REGION_ID'
);


UPDATE `dev_config` SET CONFIG_VALUE = '1.0.6' WHERE CONFIG_KEY = 'RUNXIN_SYS_VERSION';



